import SwiftUI

/// SVG path data → SwiftUI `Path`: M L H V C S Q T A Z, absolute and relative, with elliptical arcs
/// converted to cubic Béziers. The icon/emblem path strings are the same ones the Android app
/// parses (generated by android/scripts/build-icons.js with every number separated).
enum PathData {
  private static let lock = NSLock()
  private static var cache: [String: Path] = [:]

  /// Parsed once per string, then reused.
  static func path(_ d: String) -> Path {
    lock.lock()
    defer { lock.unlock() }
    if let path = cache[d] { return path }
    let path = parse(d)
    cache[d] = path
    return path
  }

  private static func parse(_ d: String) -> Path {
    var scanner = Tokens(Array(d.utf8))
    var path = Path()
    var current = CGPoint.zero
    var start = CGPoint.zero
    var lastControl: CGPoint?
    var lastCommand: UInt8 = 0
    var command: UInt8 = 0
    while let next = scanner.nextCommand(current: command) {
      command = next
      let relative = command >= 97 // lowercase
      let base = relative ? current : .zero
      switch command | 0x20 { // lowercased
      case 109: // m
        let p = scanner.point(base)
        path.move(to: p)
        current = p
        start = p
        lastControl = nil
        // Further pairs after a moveto are linetos.
        command = relative ? 108 : 76
      case 108: // l
        let p = scanner.point(base)
        path.addLine(to: p)
        current = p
        lastControl = nil
      case 104: // h
        let x = scanner.number() + (relative ? current.x : 0)
        current = CGPoint(x: x, y: current.y)
        path.addLine(to: current)
        lastControl = nil
      case 118: // v
        let y = scanner.number() + (relative ? current.y : 0)
        current = CGPoint(x: current.x, y: y)
        path.addLine(to: current)
        lastControl = nil
      case 99: // c
        let c1 = scanner.point(base), c2 = scanner.point(base), p = scanner.point(base)
        path.addCurve(to: p, control1: c1, control2: c2)
        lastControl = c2
        current = p
      case 115: // s
        let c1 = reflect(lastControl, about: current, if: [99, 115].contains(lastCommand | 0x20))
        let c2 = scanner.point(base), p = scanner.point(base)
        path.addCurve(to: p, control1: c1, control2: c2)
        lastControl = c2
        current = p
      case 113: // q
        let c = scanner.point(base), p = scanner.point(base)
        path.addQuadCurve(to: p, control: c)
        lastControl = c
        current = p
      case 116: // t
        let c = reflect(lastControl, about: current, if: [113, 116].contains(lastCommand | 0x20))
        let p = scanner.point(base)
        path.addQuadCurve(to: p, control: c)
        lastControl = c
        current = p
      case 97: // a
        let rx = scanner.number(), ry = scanner.number(), rotation = scanner.number()
        let largeArc = scanner.flag(), sweep = scanner.flag()
        let p = scanner.point(base)
        addArc(&path, from: current, to: p, rx: rx, ry: ry, rotationDegrees: rotation, largeArc: largeArc, sweep: sweep)
        current = p
        lastControl = nil
      case 122: // z
        path.closeSubpath()
        current = start
        lastControl = nil
      default:
        return path
      }
      lastCommand = command
    }
    return path
  }

  private static func reflect(_ control: CGPoint?, about p: CGPoint, if condition: Bool) -> CGPoint {
    guard condition, let control else { return p }
    return CGPoint(x: 2 * p.x - control.x, y: 2 * p.y - control.y)
  }

  /// SVG endpoint arc → center parameterization (SVG 1.1 appendix F.6) → cubic Béziers of ≤ 90°.
  private static func addArc(
    _ path: inout Path, from p0: CGPoint, to p1: CGPoint,
    rx rxIn: CGFloat, ry ryIn: CGFloat, rotationDegrees: CGFloat, largeArc: Bool, sweep: Bool
  ) {
    var rx = abs(rxIn), ry = abs(ryIn)
    if rx == 0 || ry == 0 || p0 == p1 {
      path.addLine(to: p1)
      return
    }
    let phi = rotationDegrees * .pi / 180
    let cosPhi = cos(phi), sinPhi = sin(phi)
    let dx = (p0.x - p1.x) / 2, dy = (p0.y - p1.y) / 2
    let x1 = cosPhi * dx + sinPhi * dy
    let y1 = -sinPhi * dx + cosPhi * dy
    let lambda = (x1 * x1) / (rx * rx) + (y1 * y1) / (ry * ry)
    if lambda > 1 {
      rx *= lambda.squareRoot()
      ry *= lambda.squareRoot()
    }
    let numerator = rx * rx * ry * ry - rx * rx * y1 * y1 - ry * ry * x1 * x1
    let denominator = rx * rx * y1 * y1 + ry * ry * x1 * x1
    var factor = (max(0, numerator) / denominator).squareRoot()
    if largeArc == sweep { factor = -factor }
    let cx1 = factor * rx * y1 / ry
    let cy1 = -factor * ry * x1 / rx
    let cx = cosPhi * cx1 - sinPhi * cy1 + (p0.x + p1.x) / 2
    let cy = sinPhi * cx1 + cosPhi * cy1 + (p0.y + p1.y) / 2

    func angle(_ ux: CGFloat, _ uy: CGFloat, _ vx: CGFloat, _ vy: CGFloat) -> CGFloat {
      let a = atan2(ux * vy - uy * vx, ux * vx + uy * vy)
      return a
    }
    let theta1 = angle(1, 0, (x1 - cx1) / rx, (y1 - cy1) / ry)
    var delta = angle((x1 - cx1) / rx, (y1 - cy1) / ry, (-x1 - cx1) / rx, (-y1 - cy1) / ry)
    if !sweep && delta > 0 { delta -= 2 * .pi }
    if sweep && delta < 0 { delta += 2 * .pi }

    let segments = max(1, Int((abs(delta) / (.pi / 2)).rounded(.up)))
    let step = delta / CGFloat(segments)
    let k = 4.0 / 3.0 * tan(step / 4)
    func point(_ t: CGFloat) -> CGPoint {
      let x = rx * cos(t), y = ry * sin(t)
      return CGPoint(x: cx + cosPhi * x - sinPhi * y, y: cy + sinPhi * x + cosPhi * y)
    }
    func derivative(_ t: CGFloat) -> CGPoint {
      let x = -rx * sin(t), y = ry * cos(t)
      return CGPoint(x: cosPhi * x - sinPhi * y, y: sinPhi * x + cosPhi * y)
    }
    var t = theta1
    for i in 0 ..< segments {
      let t2 = t + step
      let a = point(t), b = i == segments - 1 ? p1 : point(t2)
      let da = derivative(t), db = derivative(t2)
      path.addCurve(
        to: b,
        control1: CGPoint(x: a.x + k * da.x, y: a.y + k * da.y),
        control2: CGPoint(x: b.x - k * db.x, y: b.y - k * db.y)
      )
      t = t2
    }
  }
}

/// Reads path data: commands, numbers and single-digit arc flags.
private struct Tokens {
  let bytes: [UInt8]
  var i = 0

  init(_ bytes: [UInt8]) { self.bytes = bytes }

  private mutating func skipSeparators() {
    while i < bytes.count, bytes[i] == 32 || bytes[i] == 44 || bytes[i] == 9 || bytes[i] == 10 || bytes[i] == 13 { i += 1 }
  }

  private static func isCommand(_ c: UInt8) -> Bool {
    switch c | 0x20 {
    case 97, 99, 104, 108, 109, 113, 115, 116, 118, 122: return c != 101 && c != 69 // not 'e'/'E'
    default: return false
    }
  }

  /// The next command letter, or `current` again when numbers follow (an implicit repeat); nil at
  /// the end.
  mutating func nextCommand(current: UInt8) -> UInt8? {
    skipSeparators()
    guard i < bytes.count else { return nil }
    if Tokens.isCommand(bytes[i]) {
      defer { i += 1 }
      return bytes[i]
    }
    return current == 0 || (current | 0x20) == 122 ? nil : current
  }

  mutating func number() -> CGFloat {
    skipSeparators()
    let start = i
    if i < bytes.count, bytes[i] == 43 || bytes[i] == 45 { i += 1 } // + -
    var seenDot = false
    while i < bytes.count {
      let c = bytes[i]
      if c >= 48 && c <= 57 { i += 1 }
      else if c == 46 && !seenDot { seenDot = true; i += 1 }
      else if (c == 101 || c == 69) && i + 1 < bytes.count { // exponent
        i += 1
        if bytes[i] == 43 || bytes[i] == 45 { i += 1 }
      } else { break }
    }
    return CGFloat(Double(String(decoding: bytes[start ..< i], as: UTF8.self)) ?? 0)
  }

  mutating func flag() -> Bool {
    skipSeparators()
    guard i < bytes.count else { return false }
    defer { i += 1 }
    return bytes[i] == 49 // '1'
  }

  mutating func point(_ base: CGPoint) -> CGPoint {
    let x = number(), y = number()
    return CGPoint(x: base.x + x, y: base.y + y)
  }
}
